"""Parallel driver: extract the head-camera trajectory sidecar for ALL sequences.

Wraps `extract_camera_trajectory.extract_one` (loads the MPS closed-loop trajectory
and samples it at the motion `timestamps_us`) across a process pool, since the
per-sequence trajectory load (~1.18M poses) is ~2 min and 732 sequences sequential
would be ~24 h. Idempotent: an existing sidecar is skipped only when it postdates the
motion NPZ and its timestamps still match; stale/malformed sidecars are regenerated.
The optional ``--motion-root`` is propagated to worker reads and to its ``camera/`` output.

Output: /weka/jungbin/nymeriaplus_kimodo_proportional/camera/{Sxx}/{seq}.npz
Env: `nymeria_plus`.
"""
from __future__ import annotations
import argparse, json, os, sys, time, traceback
from concurrent.futures import ProcessPoolExecutor, as_completed
from pathlib import Path

import numpy as np

os.environ.setdefault("OMP_NUM_THREADS", "2")
os.environ.setdefault("MKL_NUM_THREADS", "2")
sys.path.insert(0, "/home/jungbin_cho/nymeria_kimodo_pipeline/camera")

MROOT = Path("/weka/jungbin/nymeriaplus_kimodo_proportional")


def _work(payload):
    subj, seq, motion_root, output_root = payload
    motion_root = Path(motion_root)
    output_root = Path(output_root)
    out = output_root / subj / f"{seq}.npz"
    if out.is_file():
        motion = motion_root / subj / f"{seq}.npz"
        try:
            with np.load(out) as camera_data, np.load(motion) as motion_data:
                timestamps_match = np.array_equal(
                    camera_data["timestamps_us"], motion_data["timestamps_us"]
                )
            if timestamps_match and out.stat().st_mtime >= motion.stat().st_mtime:
                return {"seq": seq, "status": "skip_current"}
        except Exception:
            # A malformed/stale sidecar is regenerated by extract_one below.
            pass
    try:
        from extract_camera_trajectory import extract_one
        return extract_one(
            subj,
            seq,
            motion_root=motion_root,
            output_root=output_root,
        )
    except Exception:
        return {"seq": seq, "status": "error", "trace": traceback.format_exc()[-500:]}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--motion-root", type=Path, default=MROOT)
    ap.add_argument("--workers", type=int, default=64)
    ap.add_argument("--limit", type=int, default=None)
    args = ap.parse_args()

    output_root = args.motion_root / "camera"
    seqs = [(p.parent.name, p.stem) for p in sorted(args.motion_root.glob("S*/*.npz"))]
    if args.limit:
        seqs = seqs[: args.limit]
    print(f"[run] camera-all workers={args.workers} jobs={len(seqs)}", flush=True)

    t0 = time.perf_counter()
    n_ok = n_skip = n_fail = 0
    results = []
    with ProcessPoolExecutor(max_workers=args.workers) as pool:
        futs = {
            pool.submit(_work, (*s, args.motion_root, output_root)): s for s in seqs
        }
        for i, fut in enumerate(as_completed(futs), 1):
            r = fut.result()
            results.append(r)
            st = r.get("status")
            if st == "ok": n_ok += 1
            elif st and st.startswith("skip"): n_skip += 1
            else: n_fail += 1
            if i % 20 == 0 or i == len(seqs):
                el = time.perf_counter() - t0
                print(f"  [{i}/{len(seqs)}] ok={n_ok} skip={n_skip} fail={n_fail} "
                      f"rate={i/el*60:.1f}/min eta={(len(seqs)-i)/(i/el)/60:.1f}min "
                      f"last={r.get('seq')}({st})", flush=True)
    output_root.mkdir(parents=True, exist_ok=True)
    with (output_root / "_camera_summary.json").open("w") as handle:
        json.dump(
            {"results": results, "totals": {"ok": n_ok, "skip": n_skip, "fail": n_fail}},
            handle,
            indent=2,
        )
    print(f"=== camera done {(time.perf_counter()-t0)/60:.1f} min "
          f"ok={n_ok} skip={n_skip} fail={n_fail} ===", flush=True)


if __name__ == "__main__":
    main()
